import{_ as a,C as r,o as i,c as l,E as d,a2 as o}from"./chunks/framework.BOeh4kYD.js";const _=JSON.parse('{"title":"记忆还在，不等于还能继承","description":"","frontmatter":{"title":"记忆还在，不等于还能继承","date":"2026-09-08","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"当数字员工更换模型、读写方式或嵌入模型后，需要哪些证据，才能让原有持久记忆成为新运行环境的权威记忆？","summary":"一项受控研究显示，文件完整、格式可读、向量维度相同，都不能保证新模型仍以相同方式检索和理解旧记忆。稳健的升级机制应把存储完整、语义兼容、可恢复与激活授权分成四个独立状态。","sources":["research/analysis/Q-20260908-01-memory-migration-admission.md"],"item_id":"Q-20260908-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-08-memory-must-be-readmitted-editorial-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-09-08-memory-must-be-readmitted.md","filePath":"zh/digital-employee/2026-09-08-memory-must-be-readmitted.md","lastUpdated":1788926442000}'),s={name:"zh/digital-employee/2026-09-08-memory-must-be-readmitted.md"};function n(p,e,m,h,c,u){const t=r("ArticleCover");return i(),l("div",null,[d(t,{image:"/assets/covers/daily-2026-09-08-memory-must-be-readmitted-editorial-v2.webp",kicker:"数字员工 · 每日研究",title:"记忆还在，不等于还能继承",summary:"一项受控研究显示，文件完整、格式可读、向量维度相同，都不能保证新模型仍以相同方式检索和理解旧记忆。稳健的升级机制应把存储完整、语义兼容、可恢复与激活授权分成四个独立状态。",version:"Q-20260908-01",status:"Daily Runtime V5 · 2026-09-08",languageHref:"/en/digital-employee/2026-09-08-memory-must-be-readmitted",languageLabel:"English"}),e[0]||(e[0]=o('<h1 id="记忆还在-不等于还能继承" tabindex="-1">记忆还在，不等于还能继承 <a class="header-anchor" href="#记忆还在-不等于还能继承" aria-label="Permalink to &quot;记忆还在，不等于还能继承&quot;">​</a></h1><p>一次模型升级之后，数字员工重新启动，数据库能打开，文件哈希没有变化，向量仍是 1024 维。传统完整性检查全部通过，于是系统直接接管旧记忆。</p><p>问题在于，<strong>保存下来的字节没有变，不代表新模型还能以原来的方式找到并理解其中的事实。</strong> 一项关于智能体记忆可移植性的受控研究显示，同一份自由文本记忆在不同模型之间迁移时，方向相反可能得到方向相反的效果；两个向量维度相同的嵌入版本混在同一索引中，也不能自动获得完整重建索引的效果。</p><p>本文的核心判断是：<strong>物理持久、语义兼容、具备恢复条件和获得激活授权，是四个不同状态。模型、写入器、读取器或嵌入模型发生变化后，旧记忆必须重新准入，才能成为新运行环境的权威记忆。</strong></p><h2 id="字节连续-不等于意义连续" tabindex="-1">字节连续，不等于意义连续 <a class="header-anchor" href="#字节连续-不等于意义连续" aria-label="Permalink to &quot;字节连续，不等于意义连续&quot;">​</a></h2><p>存储系统能够回答很多确定性问题：文件是否存在、数据库能否解析、字段是否符合结构、向量长度是否一致。这些检查很重要，但它们观察的是物理形态。</p><p>记忆真正服务于工作时，还要经过构造、检索和解释。写入模型决定怎样压缩事实，嵌入模型决定相似关系怎样映射到向量空间，读取模型决定怎样把取回内容转化为答案。任何一层变化，都可能让“同一份数据”在新运行环境中产生不同意义。</p><p>这不是通常所说的数据损坏。数据可以完好无损，语义合同却已经改变。如果系统只有一个“记忆可用”布尔值，就会让存储检查替代本应由语义证据和治理决定回答的问题。</p><h2 id="迁移方向为什么不能被平均值抹平" tabindex="-1">迁移方向为什么不能被平均值抹平 <a class="header-anchor" href="#迁移方向为什么不能被平均值抹平" aria-label="Permalink to &quot;迁移方向为什么不能被平均值抹平&quot;">​</a></h2><p>同日研究对象引用的主研究，对四类记忆表示、两个写入与读取模型、两个嵌入版本以及多种恢复方式进行了受控比较。</p><p>其中，自由文本笔记表现出明显的方向性：研究报告，一种“模型甲写、模型乙读”的方向相对自身笔记条件提高约 9.91 个百分点；反向迁移则下降约 13.28 个百分点。把两个方向取平均，改善与损害可能互相抵消，最终得到一个看似温和、却无法指导具体升级的结果。</p><p>嵌入迁移也出现类似问题。研究中的两个嵌入版本都输出 1024 维向量，但由新旧版本各占一半构成的混合索引，只获得完整重新嵌入的一部分收益；在所报告比较中，完整迁移比混合条件高约 6.95 个百分点。</p><p>这些数字只描述该研究的合成任务和模型组合，不能直接成为企业阈值。它们足以否定一个更弱的假设：格式相同或维度相同，不能单独证明语义兼容。准入证据必须绑定具体方向，例如“旧写入器和旧嵌入模型生成的记忆，交给新读取器和新嵌入模型”。</p><h2 id="四个状态-不能压成一个-可用" tabindex="-1">四个状态，不能压成一个“可用” <a class="header-anchor" href="#四个状态-不能压成一个-可用" aria-label="Permalink to &quot;四个状态，不能压成一个“可用”&quot;">​</a></h2><p>稳健的迁移记录至少应保留四种事实。</p><table tabindex="0"><thead><tr><th>状态</th><th>它回答什么</th><th>不能代替什么</th></tr></thead><tbody><tr><td>存储完整</td><td>数据是否存在、可解析、形态正确</td><td>新系统是否仍理解相同意义</td></tr><tr><td>语义兼容</td><td>具体迁移方向是否通过来源有据的语义探针</td><td>出错后是否能恢复</td></tr><tr><td>可恢复</td><td>是否保留允许使用的来源，以及修复程序是否在该方向上测试过</td><td>是否已经允许启用</td></tr><tr><td>激活授权</td><td>在前述证据和政策条件满足后，是否允许新运行环境使用这代记忆</td><td>兼容性的技术证明</td></tr></tbody></table><p>因此，一代记忆可以“完整但隔离”，也可以“可恢复但尚未兼容”，还可以“技术上兼容但因保留、隐私或权限政策不能启用”。显式状态不是增加文书负担，而是避免确定性程序越权替人作出语义和治理判断。</p><h2 id="最小迁移证据包应该记录什么" tabindex="-1">最小迁移证据包应该记录什么 <a class="header-anchor" href="#最小迁移证据包应该记录什么" aria-label="Permalink to &quot;最小迁移证据包应该记录什么&quot;">​</a></h2><p>一份可审计的迁移证据包，不应只写“版本升级成功”。它至少需要绑定：</p><ul><li>记忆表示、结构版本与数据代次；</li><li>原写入模型、新读取模型以及新旧嵌入模型身份；</li><li>精确迁移方向，而不是笼统的“兼容”标签；</li><li>固定且来源有据的语义探针、阈值、结果与失败样本；</li><li>在政策允许时，指向可恢复来源的出处关系；</li><li>修复程序与版本，以及该程序在当前方向上的测试结果；</li><li>最终由谁、依据哪些证据允许这代记忆进入活动状态。</li></ul><p>嵌入版本更换时，新旧语义空间应隔离或明确分代，除非系统已经证明混合方式满足当前使用目的。研究没有证明所有混合索引都无效；它证明的是，向量形状相同远不足以授权混合索引成为权威记忆。</p><h2 id="保留原始历史就一定能修好-同样过强" tabindex="-1">“保留原始历史就一定能修好”同样过强 <a class="header-anchor" href="#保留原始历史就一定能修好-同样过强" aria-label="Permalink to &quot;“保留原始历史就一定能修好”同样过强&quot;">​</a></h2><p>主研究还报告，保留原始来源能为多种恢复方式提供重要条件，完整重新嵌入在该任务中也比修复自由文本笔记稳定。但恢复并非自动成功：不同修复模型的结果仍有差异。</p><p>现实系统还会遇到研究未覆盖的边界。隐私、保留期限或合同可能禁止长期保存原始交互；企业记忆也不只有问答事实，还可能包含凭据、偏好、流程状态和外部记录。由此不能推出“永远保留全部历史”，只能推出一个更谨慎的要求：系统必须预先说明可恢复依据是什么，并验证它确实适用于当前迁移方向。</p><h2 id="升级完成的定义需要改变" tabindex="-1">升级完成的定义需要改变 <a class="header-anchor" href="#升级完成的定义需要改变" aria-label="Permalink to &quot;升级完成的定义需要改变&quot;">​</a></h2><p>对长期运行的数字员工而言，升级不应在新进程启动或数据库打开时结束。更稳健的完成条件是：物理数据已核对，具体迁移方向通过语义探针，恢复路线可用，政策门禁满足，并形成独立的激活决定。</p><p>兼容证据还应有新鲜度。模型、提示、结构、嵌入模型或检索策略发生实质变化后，旧结论可能失效。系统应把证据绑定到明确的组件组合，而不是给某个存储目录永久贴上“已兼容”。</p><h2 id="证据边界与开放问题" tabindex="-1">证据边界与开放问题 <a class="header-anchor" href="#证据边界与开放问题" aria-label="Permalink to &quot;证据边界与开放问题&quot;">​</a></h2><p>当前证据来自合成工作负载和有限模型组合，不能证明固定结构知识图谱天然安全，也不能证明自由文本记忆普遍不可靠。它提供的是迁移机制的反例和诊断线索，不是所有生产环境的最终答案。</p><p>仍需回答的问题包括：多小的语义探针集才能发现有害的方向性漂移；部分迁移期间怎样隔离不同代次；无法保留原始来源时如何设计隐私友好的恢复；哪些变化必须让激活授权自动失效；线上性能下降时，怎样区分模型能力变化、检索变化和记忆迁移失败。</p><p>在这些问题解决之前，一个稳健的默认规则是：<strong>记忆可以持久存在，但继承权必须重新获得。</strong></p><p><strong>证据与引用：</strong></p><ul><li><a href="https://arxiv.org/html/2609.05339v1" target="_blank" rel="noreferrer">智能体记忆可移植性主研究</a></li></ul>',33))])}const y=a(s,[["render",n]]);export{_ as __pageData,y as default};
